const dictionary=new Map(entries);const ordered=[...dictionary].sort((a,b)=>b[0].length-a[0].length).map(([fa,en])=>[fa,en,new RegExp('(?<![\\p{L}\\p{N}])'+fa.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'(?![\\p{L}\\p{N}])','gu')]);
let lang='fa';
export function setLanguage(value){lang=value==='en'?'en':'fa';}
export function translate(text){if(lang!=='en'||!/[\u0600-\u06ff]/.test(text))return text;const t=text.trim();if(dictionary.has(t))return text.replace(t,dictionary.get(t));let result=text;for(const[fa,en,re]of ordered){if(result.includes(fa))result=result.replace(re,()=>en);}return result.replace(/[۰-۹]/g,d=>'۰۱۲۳۴۵۶۷۸۹'.indexOf(d)).replace(/،/g,',').replace(/؛/g,';');}
export function localizeDOM(root=document){if(lang!=='en')return;for(const option of root.querySelectorAll('option:not([value])'))option.value=option.textContent;const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walk.nextNode())nodes.push(walk.currentNode);for(const node of nodes){if(node.parentElement?.closest('[data-user-content],textarea,script,style,.message p,.reply-preview,.note-content'))continue;const next=translate(node.nodeValue);if(next!==node.nodeValue)node.nodeValue=next;}for(const el of root.querySelectorAll('[aria-label],[title],[placeholder],img[alt]'))for(const attr of ['aria-label','title','placeholder','alt'])if(el.hasAttribute(attr)){const old=el.getAttribute(attr),next=translate(old);if(next!==old)el.setAttribute(attr,next);}}
export function installGuidance(root=document){
 installCalendars(root);
 for(const label of root.querySelectorAll('.field label,.ws label')){
 if(label.querySelector('[data-hint]'))continue;
 const name=label.firstChild?.textContent?.trim()||'';
 const hint= name.includes('عیار')?'عدد عیار را در هزار ثبت کن.':name.includes('وزن')?'وزن را به گرم وارد کن.':name.includes('سریال')?'شماره روی بسته را وارد کن.':name.includes('عکس')?'عکس واضح همین مورد را انتخاب کن.':'';
 if(!hint)continue;
 const field=label.control||label.querySelector('input,select,textarea');if(!field||field.closest('.hint-anchor'))continue;
 const anchor=document.createElement('span');anchor.className='hint-anchor';field.before(anchor);anchor.append(field);
 const button=document.createElement('button');button.type='button';button.dataset.hint='';button.className='hint-dot';button.textContent='ⓘ';button.ariaLabel='راهنمای '+name;
 button.onclick=e=>{e.preventDefault();e.stopPropagation();const old=document.querySelector('.hint-tip');const same=old?.parentElement===anchor;old?.remove();if(same)return;const tip=document.createElement('span');tip.className='hint-tip';tip.role='tooltip';tip.textContent=name.includes('عکس')?'از '+name.replace(/^عکس\s*/,'')+' عکس واضح بگیر.':hint;anchor.append(tip);document.addEventListener('click',()=>tip.remove(),{once:true});};anchor.append(button);
 }}
